#include <sys/signalfd.h>
#include <signal.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>

#define TARGET_SIGNAL SIGINT

int main() {
    sigset_t mask;
    int sfd;
    ssize_t s;
    struct signalfd_siginfo fsi;

    // 1. Initialize signal mask and block the signal in the thread
    sigemptyset(&mask);
    sigaddset(&mask, TARGET_SIGNAL);

    if (sigprocmask(SIG_BLOCK, &mask, NULL) == -1) {
        perror("sigprocmask");
        return 1;
    }

    // 2. Create the signalfd file descriptor
    sfd = signalfd(-1, &mask, SFD_CLOEXEC);
    if (sfd == -1) {
        perror("signalfd");
        return 1;
    }

    printf("signalfd created: %d. Waiting for signal %d (SIGINT)...
", sfd, TARGET_SIGNAL);

    // 3. Send the signal (simulate external event)
    if (raise(TARGET_SIGNAL) != 0) {
        perror("raise");
        close(sfd);
        return 1;
    }

    // 4. Read the signal notification from the file descriptor
    s = read(sfd, &fsi, sizeof(struct signalfd_siginfo));
    if (s != sizeof(struct signalfd_siginfo)) {
        perror("read");
        close(sfd);
        return 1;
    }

    // 5. Process the received signal info
    printf("Caught signal %d (si_signo: %u) from sender PID %u.\n", 
           TARGET_SIGNAL, fsi.ssi_signo, fsi.ssi_pid);

    close(sfd);
    return 0;
}
